half4 main(float2 coord){half4 c=image.eval(coord);half3 s=c.rgb/max(c.a,0.0001);half l=dot(s,half3(0.2126,0.7152,0.0722));
 half sh=1.0-smoothstep(0.0,0.55,l),hi=smoothstep(0.45,1.0,l),mi=1.0-sh-hi;
